using System.Text.Json.Serialization;
using FluentMigrator.Runner;
using FluentValidation;
using Keycloak.AuthServices.Authentication;
using Keycloak.AuthServices.Authorization;
using Keycloak.AuthServices.Common;
using Lecos.Strassennamen.Data;
using Lecos.Strassennamen.RestAPI.Authorization;
using Lecos.Strassennamen.RestAPI.Interfaces;
using Lecos.Strassennamen.RestAPI.Jobs;
using Lecos.Strassennamen.RestAPI.Services;
using Microsoft.OpenApi.Models;
using Newtonsoft.Json;
using Quartz;
using Serilog;

namespace Lecos.Strassennamen.RestAPI;

public static class Program
{
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);
        builder.Services
            .AddAuthorization()
            .AddKeycloakAuthorization()
            .AddAuthorizationServer(options => { builder.Configuration.BindKeycloakOptions(options); });

        builder.Services.AddKeycloakWebApiAuthentication(builder.Configuration);
        builder.Services
            .AddAuthorizationBuilder()
            .ConfigureAuthorization(
                builder.Configuration.GetRequiredSection("Keycloak").GetValue<string>("ClientName")
                ?? throw new ApplicationException("Missing Keycloak ClientName")
                );

        var keycloakSettings = builder.Configuration.GetRequiredSection("Keycloak").Get<KeycloakAuthenticationOptions>();
        if (keycloakSettings is null)
        {
            throw new ApplicationException("Could not read Keycloak settings!");
        }
        if (keycloakSettings.AuthServerUrl is null || keycloakSettings.Realm is null)
        {
            throw new ApplicationException("Invalid Keycloak configuration!");
        }

        var jobSettings = builder.Configuration.GetRequiredSection("Jobs").Get<JobSettings>();
        if (jobSettings is null)
        {
            throw new ApplicationException("Could not read job settings!");
        }
        if (jobSettings?.XmlExportStrassen?.Active is null || jobSettings?.XmlExportStrassen?.CronSchedule is null || jobSettings?.XmlExportStrassen?.FilePath is null)
        {
            throw new ApplicationException("Invalid XmlExportJob configuration!");
        }

        builder.ConfigureLogging();
        builder.Services.ConfigureAppServices(jobSettings);

        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddSwaggerGen(options =>
            {
                var authserverBaseUrl = $"{keycloakSettings.AuthServerUrl}realms/{keycloakSettings.Realm}/protocol/openid-connect";

                options.EnableAnnotations();
                options.AddSecurityDefinition(
                    "OAuth2",
                    new()
                    {
                        Type = SecuritySchemeType.OAuth2,
                        Flows = new()
                        {
                            Implicit = new()
                            {
                                AuthorizationUrl = new($"{authserverBaseUrl}/auth"),
                                TokenUrl = new($"{authserverBaseUrl}/token"),
                            },
                        },
                    }
                );

                options.AddSecurityRequirement(
                    new()
                    {
                        {
                            new()
                            {
                                Reference = new()
                                {
                                    Type = ReferenceType.SecurityScheme,
                                    Id = "OAuth2",
                                },
                            },
                            Array.Empty<string>()
                        },
                    }
                );
            }
        );

        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddSwaggerGen();
        builder.Services
            .AddFluentMigratorCore()
            .ConfigureRunner(r => r
                .AddSqlServer()
                .WithGlobalConnectionString(builder.Configuration.GetConnectionString("DB"))
                .ScanIn(DataConfiguration.GetAssembly())
                .For.All()
            );

        builder.Services
            .AddControllers()
            .AddJsonOptions(options => options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter()));

        ValidatorOptions.Global.LanguageManager.Culture = new("de-DE");
        builder.Services.AddValidatorsFromAssembly(typeof(Program).Assembly);

        builder.Services.AddCors(options =>
        {
            options.AddPolicy("cors", policy =>
            {
                var origins = builder.Configuration.GetSection("CorsOrigins").Get<string[]>() ?? [];
                policy.WithOrigins(origins).AllowAnyHeader().AllowCredentials().AllowAnyMethod();
            });
        });

        DataConfiguration.Configure(builder.Services, builder.Configuration);

        var app = builder.Build();

        app.MapControllers();
        app.UseHttpsRedirection();
        app.UseCors("cors");
        app.UseAuthentication();
        app.UseAuthorization();

        if (app.Environment.IsDevelopment())
        {
            app.UseSwagger();
            app.UseSwaggerUI(options =>
                options.OAuthClientId(app.Configuration.GetRequiredSection("Keycloak")["Resource"])
            );
        }

        var scope = app.Services.CreateScope();
        var runner = scope.ServiceProvider.GetRequiredService<IMigrationRunner>();
        runner.MigrateUp();
        scope.Dispose();

        app.Run();
    }

    private static void ConfigureLogging(this IHostApplicationBuilder builder)
    {
        if (builder.Configuration.GetChildren().Any(x => x.Key == "Serilog"))
        {
            Log.Logger = new LoggerConfiguration()
                .ReadFrom.Configuration(builder.Configuration)
                .CreateLogger();
            builder.Logging.AddSerilog();
        }
    }

    private static IServiceCollection ConfigureAppServices(this IServiceCollection services, JobSettings jobSettings)
    {
        services
            .AddScoped<IStrasseService, StrasseService>()
            .AddScoped<IVorgangService, VorgangService>()
            .AddScoped<IBeschlussService, BeschlussService>()
            .AddScoped<IVorgangSelectiveUpdater, VorgangSelectiveUpdater>()
            .AddHttpContextAccessor();

        services
            .AddQuartz(config =>
            {
                if (jobSettings.XmlExportStrassen?.Active is true)
                {
                    config.SetupHeartbeatJob(jobSettings);
                }
                if (jobSettings.XmlExportStrassen?.Active is true)
                {
                    config.SetupXmlExportStrassenJob(jobSettings);
                }
            })
            .AddQuartzHostedService(options => options.WaitForJobsToComplete = true);

        return services;
    }

    private static void SetupHeartbeatJob(this IServiceCollectionQuartzConfigurator config, JobSettings jobSettings)
    {
        config.AddJob<HeartbeatJob>(options => options.WithIdentity(HeartbeatJob.Key));

        config.AddTrigger(options => options
            .ForJob(HeartbeatJob.Key)
            .WithIdentity(HeartbeatJob.Trigger)
            .WithCronSchedule(jobSettings.Heartbeat?.CronSchedule ?? HeartbeatJob.DefaultCronSchedule)
        );
    }

    private static void SetupXmlExportStrassenJob(this IServiceCollectionQuartzConfigurator config, JobSettings jobSettings)
    {
        var jobData = new XmlExportStrassenJobData()
        {
            FilePath = jobSettings.XmlExportStrassen?.FilePath,
            FilterStrassenStatus = jobSettings.XmlExportStrassen?.FilterStrassenStatus
        };

        config.AddJob<XmlExportStrassenJob>(options => options.WithIdentity(XmlExportStrassenJob.Key));

        config.AddTrigger(options => options
            .ForJob(XmlExportStrassenJob.Key)
            .WithIdentity(XmlExportStrassenJob.Trigger + "RunOnceAtStart")
            .StartNow()
            .WithPriority(0)
            .WithSimpleSchedule(x => x.WithMisfireHandlingInstructionIgnoreMisfires())
            .UsingJobData(new JobDataMap() { [XmlExportStrassenJob.Name] = JsonConvert.SerializeObject(jobData) })
        );

        config.AddTrigger(options => options
            .ForJob(XmlExportStrassenJob.Key)
            .WithIdentity(XmlExportStrassenJob.Trigger)
            .WithCronSchedule(jobSettings.XmlExportStrassen?.CronSchedule ?? XmlExportStrassenJob.DefaultCronSchedule)
            .UsingJobData(new JobDataMap() { [XmlExportStrassenJob.Name] = JsonConvert.SerializeObject(jobData) })
        );
    }
}

